import { parse } from "devalue";
import { useOgImageRuntimeConfig } from "../utils.js";
import { autoEjectCommunityTemplate } from "./auto-eject.js";
import { normaliseOptions } from "./options.js";
const PAYLOAD_REGEX = /<script.+id="nuxt-og-image-options"[^>]*>(.+?)<\/script>/;
export function collectAutoEjectTemplates(html, event) {
  const payload = [...html.head, ...html.bodyAppend].join("\n").match(PAYLOAD_REGEX)?.[1];
  if (!payload)
    return;
  for (const options of parse(payload)) {
    if (!options?.component)
      continue;
    const normalised = (() => {
      try {
        return normaliseOptions({ ...options });
      } catch {
        return null;
      }
    })();
    if (normalised?.component?.category === "community")
      (event.context._ogImageAutoEject ||= []).push(normalised.component);
  }
}
export function ejectCollectedTemplates(event) {
  const components = event.context._ogImageAutoEject;
  if (!components?.length)
    return;
  const runtimeConfig = useOgImageRuntimeConfig(event);
  for (const component of components)
    autoEjectCommunityTemplate(component, runtimeConfig);
}
